    "pt-BR": "O conte\u00fado ser\u00e1 enviado para @${connectedAccount.username} para verificar o recebimento upstream",
    "tr": "Y\u00fck, yukar\u0131 ak\u0131\u015f makbuzunu do\u011frulamak i\u00e7in @${connectedAccount.username} adresine g\u00f6nderilecektir",
    "ru": "\u0422\u0435\u0441\u0442\u043e\u0432\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0431\u0443\u0434\u0435\u0442 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e \u043d\u0430 @${connectedAccount.username} \u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0434\u043e\u0441\u0442\u0430\u0432\u043a\u0438",
    "zh": "\u8f7d\u8377\u5c06\u53d1\u9001\u81f3 @${connectedAccount.username} \u4ee5\u9a8c\u8bc1\u4e0a\u6e38\u63a5\u6536\u56de\u6267",
    "ja": "\u30a2\u30c3\u30d7\u30b9\u30c8\u30ea\u30fc\u30e0\u53d7\u4fe1\u3092\u78ba\u8a8d\u3059\u308b\u305f\u3081\u30da\u30a4\u30ed\u30fc\u30c9\u3092 @${connectedAccount.username} \u306b\u914d\u4fe1\u3057\u307e\u3059"
