    "fr": "Attribuez des num\u00e9ros dans plus de 55 pays, associez WhatsApp Business et d\u00e9ployez des agents vocaux IA 24/7",
    "de": "Nummern in \u00fcber 55 L\u00e4ndern bereitstellen, WhatsApp Business verkn\u00fcpfen & 24/7 Voice-KI-Agenten einsetzen",
    "pt-BR": "Provisione n\u00fameros em mais de 55 pa\u00edses, vincule o WhatsApp Business e implante agentes de voz com IA 24/7",
    "tr": "55'ten fazla \u00fclkede numara tahsis edin, WhatsApp Business'\u0131 ba\u011flay\u0131n ve 7/24 Sesli Yapay Zeka Temsilcileri konu\u015fland\u0131r\u0131n",
    "ru": "\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435 \u043d\u043e\u043c\u0435\u0440\u0430 \u0432 55+ \u0441\u0442\u0440\u0430\u043d\u0430\u0445, \u043f\u0440\u0438\u0432\u044f\u0437\u044b\u0432\u0430\u0439\u0442\u0435 WhatsApp Business \u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0439\u0442\u0435 \u0433\u043e\u043b\u043e\u0441\u043e\u0432\u044b\u0445 \u0418\u0418-\u0430\u0433\u0435\u043d\u0442\u043e\u0432 24/7",
    "zh": "\u5728 55+ \u4e2a\u56fd\u5bb6/\u5730\u533a\u914d\u7f6e\u53f7\u7801\uff0c\u7ed1\u5b9a WhatsApp Business \u5e76\u90e8\u7f72 24/7 \u5168\u5929\u5019 AI \u8bed\u97f3\u4ee3\u7406",
    "ja": "55\u304b\u56fd\u4ee5\u4e0a\u306e\u756a\u53f7\u3092\u767a\u884c\u3057\u3001WhatsApp Business \u3092\u9023\u643a\u300124\u6642\u9593365\u65e5\u7a3c\u50cd\u306eAI\u97f3\u58f0\u30a8\u30fc\u30b8\u30a7\u30f3\u30c8\u3092\u5c55\u958b"
