    "pt-BR": "Escolha como receber a verifica\u00e7\u00e3o. O SMS de entrada \u00e9 capturado automaticamente no seu n\u00famero virtual.",
    "tr": "Do\u011frulamay\u0131 nas\u0131l alaca\u011f\u0131n\u0131z\u0131 se\u00e7in. Gelen SMS, sanal numaran\u0131zda otomatik olarak yakalan\u0131r.",
    "ru": "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043f\u043e\u0441\u043e\u0431 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438. \u0412\u0445\u043e\u0434\u044f\u0449\u0438\u0435 SMS \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u0432\u0430\u0448\u0435\u043c \u0432\u0438\u0440\u0442\u0443\u0430\u043b\u044c\u043d\u043e\u043c \u043d\u043e\u043c\u0435\u0440\u0435 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438.",
    "zh": "\u9009\u62e9\u63a5\u6536\u9a8c\u8bc1\u7801\u7684\u65b9\u5f0f\u3002\u63a5\u6536\u5230\u7684\u77ed\u4fe1\u5c06\u81ea\u52a8\u5728\u60a8\u7684\u865a\u62df\u53f7\u7801\u4e0a\u6355\u83b7\u3002",
    "ja": "\u78ba\u8a8d\u30b3\u30fc\u30c9\u306e\u53d7\u4fe1\u65b9\u6cd5\u3092\u9078\u629e\u3057\u307e\u3059\u3002\u7740\u4fe1SMS\u306f\u4eee\u60f3\u756a\u53f7\u3067\u81ea\u52d5\u30ad\u30e3\u30d7\u30c1\u30e3\u3055\u308c\u307e\u3059\u3002"
