    "tr": "Canl\u0131 \u00c7ift Tarafl\u0131 Konu\u015fma D\u00f6k\u00fcm\u00fc Ak\u0131\u015f\u0131:",
    "ru": "\u041f\u043e\u0442\u043e\u043a\u043e\u0432\u0430\u044f \u0440\u0430\u0441\u0448\u0438\u0444\u0440\u043e\u0432\u043a\u0430 \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0430 \u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c \u0432\u0440\u0435\u043c\u0435\u043d\u0438:",
