    "pt-BR": "Conectado a ${credPlatform.toUpperCase()} com sucesso!",
    "tr": "${credPlatform.toUpperCase()} ba\u015far\u0131yla ba\u011fland\u0131!",
    "ru": "\u0423\u0441\u043f\u0435\u0448\u043d\u043e \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 ${credPlatform.toUpperCase()}!",
