  "Manage active channels, monitor token health, and trigger live delivery verification tests": {
    "ar": "\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0642\u0646\u0648\u0627\u062a \u0627\u0644\u0641\u0639\u0627\u0644\u0629\u060c \u0645\u0631\u0627\u0642\u0628\u0629 \u0635\u062d\u0629 \u0627\u0644\u0631\u0645\u0648\u0632\u060c \u0648\u0625\u062c\u0631\u0627\u0621 \u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0646\u0634\u0631 \u0627\u0644\u062d\u064a \u0627\u0644\u0641\u0648\u0631\u064a\u0629",
    "en": "Manage active channels, monitor token health, and trigger live delivery verification tests",
    "es": "Administre canales activos, supervise el estado de los tokens e inicie pruebas de verificaci\u00f3n de entrega en vivo",
    "fr": "G\u00e9rez les canaux actifs, surveillez l'\u00e9tat des jetons et lancez des tests de v\u00e9rification de diffusion en direct",
    "de": "Aktive Kan\u00e4le verwalten, Token-Zustand \u00fcberwachen und Live-Zustellungspr\u00fcfungen durchf\u00fchren",
    "pt-BR": "Gerencie canais ativos, monitore a integridade dos tokens e execute testes de verifica\u00e7\u00e3o de entrega ao vivo",
    "tr": "Aktif kanallar\u0131 y\u00f6netin, belirte\u00e7 durumunu izleyin ve canl\u0131 teslimat do\u011frulama testleri ba\u015flat\u0131n",
    "ru": "\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u0439\u0442\u0435 \u0430\u043a\u0442\u0438\u0432\u043d\u044b\u043c\u0438 \u043a\u0430\u043d\u0430\u043b\u0430\u043c\u0438, \u043e\u0442\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u0442\u0430\u0442\u0443\u0441 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0439\u0442\u0435 \u0442\u0435\u0441\u0442\u044b \u0434\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c \u0432\u0440\u0435\u043c\u0435\u043d\u0438",
    "zh": "\u7ba1\u7406\u6d3b\u8dc3\u6e20\u9053\u3001\u76d1\u63a7\u4ee4\u724c\u5065\u5eb7\u72b6\u6001\u5e76\u89e6\u53d1\u5b9e\u65f6\u4ea4\u4ed8\u9a8c\u8bc1\u6d4b\u8bd5",
    "ja": "\u6709\u52b9\u306a\u30c1\u30e3\u30f3\u30cd\u30eb\u3092\u7ba1\u7406\u3057\u3001\u30c8\u30fc\u30af\u30f3\u306e\u72b6\u614b\u3092\u76e3\u8996\u3057\u3001\u30ea\u30a2\u30eb\u30bf\u30a4\u30e0\u306e\u914d\u4fe1\u78ba\u8a8d\u30c6\u30b9\u30c8\u3092\u5b9f\u884c"
  },
