    "ru": "\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0443 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u044b, \u0447\u0442\u043e\u0431\u044b \u043e\u0442\u043a\u0440\u044b\u0442\u044c 4-\u044d\u0442\u0430\u043f\u043d\u044b\u0439 \u043c\u0430\u0441\u0442\u0435\u0440 \u0441 \u0430\u0432\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u0435\u0439 OAuth \u0438 \u0432\u044b\u0431\u043e\u0440\u043e\u043c \u0441\u0442\u0440\u0430\u043d\u0438\u0446",
