    "tr": "Techurity'yi https://techurity.si/api/v1 \u00fczerinden kendi web sitenize, uygulaman\u0131za veya yapay zeka temsilcinize entegre etmek i\u00e7in bu anahtar\u0131 kullan\u0131n:",
